  (* [comment removed for export] *)
  Lemma pn_F3 : forall regs m,
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x19098 : word) m rom) (mkst regs' (0x17c74 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x11d22 /\ getr regs' 11 = Z_to_bv 64 0x10ab5 /\ getr regs' 12 = Z_to_bv 64 0 /\ getr regs' 1 = Z_to_bv 64 0x190c4
      /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
Proof.
